    #[test]
    fn standard_resident_selection_preserves_protocol_and_stream_population() {
        use clap::Parser;
        for streams in [0, 1, 3, 8] {
            let cli = super::Cli::try_parse_from([
                "nhs_rt_full",
                "--topology",
                "unopened.json",
                "--metal-resident-md",
                "--multi-stream",
                &streams.to_string(),
                "--temperature",
                "297.25",
                "--cryo-temp",
                "73.5",
                "--steps",
                "1234567",
            ])
            .unwrap();
            assert!(super::native_chunked_producer_requested(&cli.args));
            assert!(!cli.args.multi_differential);
            assert_eq!(cli.args.multi_stream, streams);
            assert_eq!(cli.args.temperature, 297.25);
            assert_eq!(cli.args.cryo_temp, 73.5);
            assert_eq!(
                multi_stream_campaign_step_target(cli.args.steps, true, &[]).unwrap(),
                1234567
            );
        }
        assert_eq!(
            super::native_stream_protocol_name(false, false, 0),
            "standard"
        );
        assert_eq!(
            super::native_stream_protocol_name(false, true, 0),
            "multi_temperature"
        );
        assert_eq!(
            super::native_stream_protocol_name(true, false, 0),
            "ThermalShock"
        );
    }

