    #[test]
    fn selected_asc_closeout_requires_consumed_decision_but_accepts_prune() {
        let receipt = serde_json::json!({
            "support_mode": "SELECTED_STRUCTURAL_ATOM_RESIDUE_SUPPORT", "selected_atom_count": 2,
            "status_code": 1, "physical_epoch": 12, "completed_epoch": 12,
            "active_decision": {"producer_epoch": 10, "valid": 0},
            "decisions_produced": 1, "consumed_steps": 12, "coverage_failures": 0,
            "phases": [{"composed_atoms": 2, "consumed_atoms": 2, "nonzero_force_atoms": 0},
                {"composed_atoms": 2, "consumed_atoms": 2, "nonzero_force_atoms": 0}],
        });
        super::verify_selected_asc_closeout(&receipt).unwrap();
        for (pointer, value) in [
            ("/active_decision/producer_epoch", 0),
            ("/active_decision/producer_epoch", 12),
            ("/decisions_produced", 0),
            ("/consumed_steps", 0),
            ("/status_code", 2),
            ("/coverage_failures", 1),
            ("/completed_epoch", 11),
            ("/phases/0/consumed_atoms", 1),
            ("/phases/1/composed_atoms", 1),
        ] {
            let mut invalid = receipt.clone();
            *invalid.pointer_mut(pointer).unwrap() = serde_json::json!(value);
            assert!(
                super::verify_selected_asc_closeout(&invalid).is_err(),
                "accepted {pointer}={value}"
            );
        }
    }

