    fn protocol_cap_bypass_uses_the_requested_exact_campaign_horizon() {
        // The four protocols remain phase-distinct and can have different
        // total lengths after their warm-hold floor is applied.  A 500k
        // operator request must nevertheless schedule the common 500k
        // physical-step horizon rather than inherit their maximum total.
        let per_group_totals = [509_000, 508_000, 505_000, 516_000];
        let target = multi_stream_campaign_step_target(500_000, true, &per_group_totals)
            .expect("requested multi-stream campaign is valid");
        assert_eq!(target, 500_000);
        assert_eq!(
            multi_stream_campaign_chunk_count(target, 10)
                .expect("cadence-10 resident chunk is valid"),
            50_000
        );
    }

