#[cfg(test)]
mod explicit_ghost_lattice_fail_closed_tests {
    use super::{
        admit_ghost_persistence_ownership, auto_ghost_lattice_requested,
        enforce_explicit_ghost_lattice_outcome, ghost_lineage_required_at_build,
        GhostPersistenceOwnership,
    };

    #[test]
    fn explicit_success_is_admitted() {
        enforce_explicit_ghost_lattice_outcome(true, "ok")
            .expect("successful explicit lattice routing must continue");
    }

    #[test]
    fn every_explicit_failure_class_is_rejected() {
        for status in [
            "failure_v2_starved",
            "failure_v2_records_unreadable",
            "failure_no_v2_records_projected",
            "failure_lattice_kernel_error",
            "failure_cuda_init",
            "failure_no_v2_records_on_disk",
            "not_requested",
        ] {
            let error = enforce_explicit_ghost_lattice_outcome(true, status)
                .expect_err("an explicit lattice failure must terminate the engine");
            let rendered = error.to_string();
            assert!(rendered.contains(status));
            assert!(rendered.contains("gpu-hash fallback is forbidden"));
        }
    }

    #[test]
    fn automatic_ghost_intent_is_selected_before_runtime_success_is_known() {
        assert!(auto_ghost_lattice_requested("auto", true, true));
        assert!(!auto_ghost_lattice_requested("auto", false, true));
        assert!(!auto_ghost_lattice_requested("auto", true, false));
        assert!(!auto_ghost_lattice_requested("gpu-hash", true, true));

        let error = enforce_explicit_ghost_lattice_outcome(
            auto_ghost_lattice_requested("auto", true, true),
            "auto_failure_v2_starved",
        )
        .expect_err("selected automatic Ghost intent must fail closed when V2 is starved");
        assert!(error.to_string().contains("auto_failure_v2_starved"));
    }

    #[test]
    fn automatic_mode_without_ghost_intent_can_continue() {
        enforce_explicit_ghost_lattice_outcome(false, "not_requested")
            .expect("auto mode with no Ghost intent may continue to its configured backend");
    }

    #[test]
    fn ring_and_exact_clock_are_required_at_build_admission() {
        assert!(ghost_lineage_required_at_build(
            "ghost-phase-lattice-4d",
            true,
            true,
            false,
        ));
        assert!(ghost_lineage_required_at_build("auto", true, true, false,));
        assert!(ghost_lineage_required_at_build(
            "gpu-hash", false, false, true,
        ));
        assert!(!ghost_lineage_required_at_build(
            "gpu-hash", true, true, false,
        ));
    }

    #[test]
    fn mar_v1_admits_segment_only_persistence_without_exact_coordinates() {
        assert_eq!(
            admit_ghost_persistence_ownership(true, true, false, None, false)
                .expect("MAR v1 ring and segment writer are a supported durable product"),
            GhostPersistenceOwnership::SegmentOnlyMarV1,
        );
        assert_eq!(
            admit_ghost_persistence_ownership(false, false, false, None, false)
                .expect("a run with no Ghost product remains disabled"),
            GhostPersistenceOwnership::Disabled,
        );
    }

    #[test]
    fn mar_v1_rejects_an_exact_coordinate_writer_without_device_clock() {
        let error = admit_ghost_persistence_ownership(true, true, true, None, false)
            .expect_err("MAR v1 must never claim exact coordinate lineage");
        assert!(error.contains("GHOST_MAR_V1_COORDINATE_FORBIDDEN"));
    }

    #[test]
    fn mar_v2_requires_complete_exact_coordinate_ownership() {
        assert_eq!(
            admit_ghost_persistence_ownership(true, true, true, Some(1), true)
                .expect("MAR v2 with a real device counter owns the exact product"),
            GhostPersistenceOwnership::ExactCoordinateMarV2,
        );

        let missing_counter = admit_ghost_persistence_ownership(true, true, true, Some(0), true)
            .expect_err("a null MAR-v2 device counter must fail closed");
        assert!(missing_counter.contains("GHOST_MAR_V2_COUNTER_MISSING"));

        let incomplete = admit_ghost_persistence_ownership(true, true, false, Some(1), true)
            .expect_err("MAR v2 cannot omit its exact coordinate writer");
        assert!(incomplete.contains("GHOST_MAR_V2_OWNERSHIP_INCOMPLETE"));
    }

    #[test]
    fn partial_or_required_lineage_ownership_is_rejected() {
        let partial = admit_ghost_persistence_ownership(true, false, false, None, false)
            .expect_err("a staging ring without its segment writer must fail closed");
        assert!(partial.contains("GHOST_SEGMENT_OWNERSHIP_PARTIAL"));

        let required = admit_ghost_persistence_ownership(true, true, false, None, true)
            .expect_err("an exact-lineage request cannot silently fall back to MAR v1");
        assert!(required.contains("GHOST_REQUIRED_LINEAGE_NEEDS_MAR_V2"));
    }

    #[test]
    fn fail_closed_guard_precedes_v2_teardown_and_legacy_routing() {
        let source = include_str!("nhs_rt_full.rs");
        let guard = source
            .rfind(
                "enforce_explicit_ghost_lattice_outcome(\n        lattice_explicit_request || lattice_auto_request,",
            )
            .expect("production fail-closed guard must be present");
        let v2_teardown = source[guard..]
            .find("if v2_was_live_for_lattice {")
            .map(|offset| guard + offset)
            .expect("V2 teardown must remain present after routing");
        assert!(guard < v2_teardown);
    }
}

#[cfg(test)]
mod engine_dispatch_tests {
    use super::*;

    /// Adjudicate against the DOCUMENTED COMPILED DEFAULTS (stream floor 8,
    /// bridge group count 4) so the pinned assertions below never depend on an
    /// operator policy document or on the process environment. Not a `#[test]`,
    /// so the binary's test count is unchanged.
    fn admit_dispatch(
        multi_differential: bool,
        coupled_twin: bool,
        graph_coupling: bool,
        multi_stream: usize,
        wall_bound_requested: bool,
    ) -> (&'static str, &'static str, &'static str) {
        let topology = prism_nhs::physical_governor::resolve_stream_topology_layered(
            None,
            None,
            prism_nhs::physical_governor::StreamTopologyOverrides::default(),
            prism_nhs::physical_governor::StreamTopologyOverrides::default(),
        )
        .expect("documented stream-topology defaults must resolve");
        adjudicate_engine_dispatch(
            &EngineDispatchRequest {
                multi_differential,
                coupled_twin,
                graph_coupling,
                multi_stream,
                wall_bound_requested,
            },
            &topology,
        )
        .as_tuple()
    }

    #[test]
    fn named_surface_dispatch_conflicts_and_unimplemented_graph_paths_fail_closed() {
        assert_eq!(
            admit_dispatch(true, true, true, 8, true),
            (
                "FAIL",
                "multi_differential",
                "MULTI_DIFFERENTIAL_AND_COUPLED_TWIN_CONFLICT"
            )
        );
        assert_eq!(
            admit_dispatch(false, true, true, 8, false),
            (
                "FAIL",
                "coupled_twin",
                "GROUPED_COUPLED_GRAPH_CAPTURE_NOT_IMPLEMENTED"
            )
        );
        assert_eq!(
            admit_dispatch(false, true, false, 1, true),
            (
                "FAIL",
                "coupled_twin",
                "COUPLED_TWIN_WALL_BOUND_NOT_IMPLEMENTED"
            )
        );
        assert_eq!(
            admit_dispatch(true, false, false, 8, true),
            ("PASS", "multi_differential", "ADMITTED")
        );
        // The historical eight-stream captured-graph run: still admitted, and
        // still admitted for the same arithmetic reason (8 >= 8, 8 % 4 == 0).
        assert_eq!(
            admit_dispatch(true, false, true, 8, true),
            ("PASS", "captured_graph_twin_multi_stream", "ADMITTED")
        );
        // n=7: below the floor AND a partial bridge group.
        assert_eq!(
            admit_dispatch(true, false, true, 7, true),
            (
                "FAIL",
                "captured_graph_twin_multi_stream",
                "CAPTURED_GRAPH_TWIN_STREAM_TOPOLOGY"
            )
        );
        // n=16: the TWIN16 factorial topology. 16 >= 8 and 16 % 4 == 0, so
        // captured-graph + TWIN16 is admissible instead of refused by a source
        // literal. This is the capability the work exists to unblock.
        assert_eq!(
            admit_dispatch(true, false, true, 16, true),
            ("PASS", "captured_graph_twin_multi_stream", "ADMITTED")
        );
        // n=10: clears a bare `>= 8` floor, but epg_val = (10/4).max(1) = 2 and
        // stream 9 yields group_idx 4 against four-element per-group state. The
        // congruence must keep this a clean pre-CUDA refusal, not a panic after
        // the lease is paid.
        assert_eq!(
            admit_dispatch(true, false, true, 10, true),
            (
                "FAIL",
                "captured_graph_twin_multi_stream",
                "CAPTURED_GRAPH_TWIN_STREAM_TOPOLOGY"
            )
        );
    }
}

