    #[cfg(feature = "gpu")]
    #[test]
    fn admitted_full_reaches_the_production_post_md_dispatch() {
        use std::cell::Cell;

        let route = resolve_post_md_route(
            PostMdAggregationPolicy::Full,
            PostMdLane::CoupledMulti,
            true,
            false,
        );
        assert_eq!(route.effective, EffectivePostMdAggregation::Full);
        let inputs = CoupledMultiPostMdInputs {
            group_a_spikes: vec![prism_nhs::fused_engine::GpuSpikeEvent::default()],
            group_b_spikes: vec![prism_nhs::fused_engine::GpuSpikeEvent::default()],
            group_a_snapshots: Vec::new(),
            group_b_snapshots: Vec::new(),
        };
        assert!(
            !inputs.group_a_spikes.is_empty() && !inputs.group_b_spikes.is_empty(),
            "non-vacuity: Full dispatch requires physical inputs"
        );
        let handoff_calls = Cell::new(0usize);
        let postprocess_calls = Cell::new(0usize);
        let outcome = dispatch_coupled_multi_post_md(
            route,
            inputs,
            |_inputs| {
                handoff_calls.set(handoff_calls.get() + 1);
                Ok(())
            },
            |inputs| {
                postprocess_calls.set(postprocess_calls.get() + 1);
                Ok(inputs.group_a_spikes.len() + inputs.group_b_spikes.len())
            },
        )
        .expect("authorized Full route must execute post-MD");
        assert_eq!(outcome, Some(2));
        assert_eq!(handoff_calls.get(), 0);
        assert_eq!(postprocess_calls.get(), 1);

        let source = include_str!("nhs_rt_full.rs");
        let dispatch_call = source
            .find("let result = dispatch_coupled_multi_post_md(")
            .expect("production dispatch exists");
        let production_tail = &source[dispatch_call..];
        assert!(
            production_tail.contains("twin_post_process("),
            "production Full callback must remain the native post-MD stage"
        );
    }

    #[test]
    fn canonical_lattice_binding_rows_use_materialized_identity_for_all_therm_consumers() {
        use prism_nhs::sdst_bridge::{
            materialize_lattice_sites, SdstAnalysisOutcome, SdstAnalysisStatus, TideResidueResult,
        };

        let sites = materialize_lattice_sites(&[
            (7, [1.0, 2.0, 3.0], [3.0, 6.0, 9.0]),
            (11, [10.0, 20.0, 30.0], [12.0, 24.0, 36.0]),
        ])
        .expect("materialize adversarial lattice fixture");
        assert_eq!(sites.len(), 2, "non-vacuity: two sites required");
        let therm_row = |identity, materialized_site_id, is_hysteretic| PrismThermSiteResult {
            analyzed_site_identity: identity,
            materialized_site_id,
            site_id: materialized_site_id.map_or(-1, |id| id.0 as i32),
            asymmetry_score: if is_hysteretic { 0.8 } else { 0.1 },
            is_hysteretic,
            heating_spike_rate: 1.0,
            cooling_spike_rate: 0.2,
            heating_spike_count: 10,
            cooling_spike_count: 2,
            tau: 1.25,
            tau_stderr: 0.05,
            ccns_classification: "Soc".to_string(),
            druggability: 0.85,
            n_avalanches: 3,
            relative_asymmetry: 1.4,
            therm_class: ThermClass::Dynamic,
            tide_decomposition: vec![TideResidueResult {
                residue_id: 42,
                causal_dg: -0.7,
                transfer_entropy: 0.63,
                fisher_info: 0.4,
                kl_divergence: 0.2,
                n_causal_spikes: 5,
                measurement_support: serde_json::Value::Null,
            }],
        };
        // Numerically equal CCL row comes first and must not win the lattice
        // join. The second materialized site is deliberately unmatched.
        let analysis = PrismThermAnalysis {
            outcome: SdstAnalysisOutcome {
                status: SdstAnalysisStatus::Complete,
                requested_site_count: 2,
                materialized_site_count: 1,
                stages: Vec::new(),
            },
            sdst_event_count: 12,
            hysteresis_threshold: 0.2,
            hysteretic_site_count: 1,
            sites: vec![
                therm_row(
                    AnalyzedSiteIdentity::Cluster(ClusterId(sites[0].materialized_site_id.0)),
                    None,
                    false,
                ),
                therm_row(
                    sites[0].analyzed_site_identity,
                    Some(sites[0].materialized_site_id),
                    true,
                ),
            ],
            global_pockets: Vec::new(),
            total_avalanches: 3,
            tide_residues_mapped: 1,
        };
        let conservation = reconcile_lattice_site_population(
            sites.len(),
            &sites,
            &analysis,
            LatticeMaterializationRequirement::Optional,
            "canonical_binding_sites_collection",
        )
        .expect("terminal conservation");
        let projections = project_lattice_binding_sites(&sites).expect("typed projection");
        let rows = lattice_binding_site_rows(&projections, &analysis, &conservation)
            .expect("canonical lattice binding rows");
        assert_eq!(rows.len(), 2);
        assert_eq!(rows[0]["identity_join"], "MaterializedSiteId");
        assert_eq!(rows[0]["therm_class"], "DYNAMIC");
        assert_eq!(rows[0]["hysteresis_positive"], true);
        let transfer_entropy = rows[0]["candidate_transfer_entropy"][0]
            .as_f64()
            .expect("typed transfer entropy");
        assert!((transfer_entropy - 0.63).abs() < 1.0e-6);
        assert!(rows[0].get("cluster_id").is_none());
        assert_eq!(rows[1]["terminal_disposition"], "UNMATCHED");
        assert_eq!(rows[1]["unmatched_reason"], "MISSING_COMPANION_DATA");
        assert!(rows[1].get("therm_class").is_none());
        assert_eq!(rows[1]["centroid"], serde_json::json!([11.0, 22.0, 33.0]));
    }

