fn prismcode_cuda_graph_scientific_state_boundary_summary(
    receipts: &[serde_json::Value],
) -> serde_json::Value {
    let mut boundaries = Vec::new();
    let mut capture_boundary_count = 0usize;
    let mut replay_boundary_count = 0usize;
    let mut window_metadata_count = 0usize;
    let mut forbidden_side_effect_metadata_count = 0usize;

    for receipt in receipts {
        let stream_id = receipt
            .get("stream_id")
            .and_then(|value| value.as_u64())
            .map(serde_json::Value::from)
            .unwrap_or(serde_json::Value::Null);
        let Some(dispatches) = receipt
            .get("sample_dispatches")
            .and_then(|value| value.as_array())
        else {
            continue;
        };
        for dispatch in dispatches {
            let Some(note) = dispatch.get("note").and_then(|value| value.as_str()) else {
                continue;
            };
            let Ok(mut metadata) = serde_json::from_str::<serde_json::Value>(note) else {
                continue;
            };
            if metadata.get("schema_kind").and_then(|value| value.as_str())
                != Some("prism_cuda_graph_scientific_state_boundary")
            {
                continue;
            }
            match metadata.get("event_kind").and_then(|value| value.as_str()) {
                Some("capture") => capture_boundary_count += 1,
                Some("replay") => replay_boundary_count += 1,
                _ => {}
            }
            if metadata.get("logical_step_window").is_some() {
                window_metadata_count += 1;
            }
            if metadata.get("forbidden_side_effects").is_some() {
                forbidden_side_effect_metadata_count += 1;
            }
            if let Some(obj) = metadata.as_object_mut() {
                obj.insert("stream_id".to_string(), stream_id.clone());
                obj.insert(
                    "dispatch_step".to_string(),
                    dispatch
                        .get("step")
                        .cloned()
                        .unwrap_or(serde_json::Value::Null),
                );
                obj.insert(
                    "dispatch_phase".to_string(),
                    dispatch
                        .get("phase")
                        .cloned()
                        .unwrap_or(serde_json::Value::Null),
                );
            }
            boundaries.push(metadata);
        }
    }

    let boundary_count = boundaries.len();
    serde_json::json!({
        "schema_kind": "prism_cuda_graph_scientific_state_boundary_summary",
        "schema_version": 1,
        "source": "PrismCode native MD sample_dispatches.note",
        "boundary_count": boundary_count,
        "capture_boundary_count": capture_boundary_count,
        "replay_boundary_count": replay_boundary_count,
        "window_metadata_count": window_metadata_count,
        "forbidden_side_effect_metadata_count": forbidden_side_effect_metadata_count,
        "window_aware": boundary_count > 0 && window_metadata_count == boundary_count,
        "forbidden_side_effects_available": boundary_count > 0
            && forbidden_side_effect_metadata_count == boundary_count,
        "chronology_ready": boundaries.iter().any(|boundary| {
            boundary
                .get("chronology")
                .and_then(|chronology| chronology.get("ready"))
                .and_then(|ready| ready.as_bool())
                .unwrap_or(false)
        }),
        "sample_limit_note": "receipt sample_dispatches are capped by the PrismCode runtime; aggregate graph counts remain in receipt top-level fields",
        "boundaries": boundaries,
    })
}

