        for (step, positions) in [
            (5_000u64, vec![1.0f32, -2.0, 3.5, 4.0, 5.25, -6.75]),
            (10_000u64, vec![7.0f32, 8.5, 9.25, -10.0, 11.5, 12.75]),
        ] {
            let producer_hash64 = v2_trajectory_frame_hash(step, &positions);
            tx.send(V2TrajectoryFrame {
                step,
                positions,
                producer_hash64,
            })?;
        }
