                        let mut phase_a_bocpd_w=prism_nhs::native_run_continuation::open_writer(continuation_saved,"writer:phase_a_bocpd",&output_path_capture,&phase_a_bocpd_path,false)?;
                        let mut phase_a_adj_w=prism_nhs::native_run_continuation::open_writer(continuation_saved,"writer:phase_a_adj",&output_path_capture,&phase_a_adj_path,false)?;
                        let mut phase_a_dt_w=prism_nhs::native_run_continuation::open_writer(continuation_saved,"writer:phase_a_dt",&output_path_capture,&phase_a_dt_path,false)?;
                        let mut phase_a_asc_w=prism_nhs::native_run_continuation::open_writer(continuation_saved,"writer:phase_a_asc",&output_path_capture,&phase_a_asc_path,false)?;
