                                    metadata["parameter_law"]=serde_json::json!("k=min(2.0*(300.0/max(T,10.0)),50.0);alpha=min(k*0.001,0.1); applies only when the original ordinary caller invokes CA relaxation; autonomous/step_batch rows have applied alpha zero");
                                    metadata["state_changes"]=serde_json::json!("ordinary caller: original CA coordinate projection without added post-projection SHAKE/RATTLE or endpoint force/PE recomputation; autonomous/step_batch caller: observation only, no CA projection; existing force/PE buffers preserved");
