                        let ca_atom_work_path=output_path_capture.join(format!("{}_stream{:02}_ca_coordinate_work.f64le",resident_traj_stem,i));
                        let ca_atom_index_path=output_path_capture.join(format!("{}_stream{:02}_ca_coordinate_work.index.jsonl",resident_traj_stem,i));
                        let ca_atom_manifest_path=output_path_capture.join(format!("{}_stream{:02}_ca_coordinate_work.manifest.json",resident_traj_stem,i));
