                        let energy_balance_path=output_path_capture.join(format!("{}_stream{:02}_physical_energy_balance.jsonl",resident_traj_stem,i));
                        let energy_balance_manifest_path=output_path_capture.join(format!("{}_stream{:02}_physical_energy_balance.manifest.json",resident_traj_stem,i));
                        let energy_balance_completion_path=output_path_capture.join(format!("{}_stream{:02}_physical_energy_balance.completion.json",resident_traj_stem,i));
