                            manifest["coverage_policy"]=serde_json::json!("every ordinary physical step, all three native constraint phases and every loaded atom including zero entries; exact native step retained without fabricated physical time");
                            manifest["persistence"]=serde_json::json!("clock when present, compressed bytes and index file synced before native window retirement; initial output directory entries synced");
                            manifest["completion_source"]=serde_json::json!("indexed realized windows and separate completion receipt; configured horizon is not executed coverage");
