const NATIVE_SHARED_CONTINUATION_KEYS:&[&str]=&["native_md_budget_continuation", "raw_chronicle", "asc_shared", "captured_endpoint", "native_modules", "native_provider_identity", "native_historical_branch_origin", "native_collective_boundary", "ordinary_rings", "protocol_globals", "scientific_chronology", "shared:ASC_STREAM_RECEIPTS", "shared:GOVERNOR_STREAM_RECEIPTS", "shared:active_wall_elapsed_ns", "shared:chronology_emitted_subchunk_marker_events", "shared:chronology_expected_frame_capture_events", "shared:chronology_expected_subchunk_marker_events", "shared:coupling_source_counts", "shared:path_a_evidence_complete", "shared:path_a_exit_reason", "shared:path_a_instantiate_complete_by_stream", "shared:path_a_t7_chunks_completed", "shared:path_a_v2_trigger_by_stream", "shared:v2_was_live", "shared:wb_done"];

#[cfg(feature="gpu")]
fn native_cuda_provider_identity(context:&std::sync::Arc<cudarc::driver::CudaContext>)->Result<BTreeMap<String,String>> {
    let mut values=BTreeMap::new();let mut driver=0;
    let rc=unsafe{cudarc::driver::sys::cuDriverGetVersion(&mut driver)};
    anyhow::ensure!(rc==cudarc::driver::sys::CUresult::CUDA_SUCCESS,"CUDA driver version read failed {rc:?}");
    values.insert("driver_version".into(),driver.to_string());
    values.insert("gpu_name".into(),context.name()?);
    values.insert("gpu_uuid".into(),serde_json::to_string(&context.uuid()?.bytes)?);
    values.insert("compute_capability".into(),serde_json::to_string(&context.compute_capability()?)?);
    // Bind the provider actually mapped into this process, including native
    // SDST and CUDA dependencies, against each opened descriptor's device/inode.
    values.extend(prism_nhs::native_run_continuation::mapped_native_library_identities()?);
    anyhow::ensure!(values.keys().any(|k|k.contains("libcuda.so")),"actual CUDA provider mapping absent");Ok(values)
}
